import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

triplet_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor triplet_margin_loss(torch::Tensor anchor,
                                  torch::Tensor positive,
                                  torch::Tensor negative,
                                  double margin);
"""

triplet_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Single fused kernel:
//   loss_i = max(||a_i - p_i||_2 - ||a_i - n_i||_2 + margin, 0)
//   output = mean_i(loss_i)
// Optimization: map one warp per sample row instead of one CTA per row.
// Each 256-thread CTA now covers 8 adjacent rows; every warp performs an
// independent warp-shuffle reduction with no shared-memory staging and no
// __syncthreads(). This increases useful work per CTA, cuts the number of
// scheduled CTAs by 8x, removes cross-warp reduction sync overhead, and
// keeps global loads coalesced at float4 granularity within each row. New: use __ldcs streaming (evict-first) loads since every input row is read exactly once and has zero reuse, reducing L2 cache pollution/thrashing for this bandwidth-bound reduction.
template <int Threads>
__global__ void triplet_margin_loss_kernel(
    const float* __restrict__ A,
    const float* __restrict__ P,
    const float* __restrict__ N,
    float* __restrict__ out,
    int B, int D,
    float margin, float inv_n)
{
  constexpr int Warps = Threads / 32;
  const int lane = threadIdx.x & 31;
  const int warp = threadIdx.x >> 5;
  const int row = blockIdx.x * Warps + warp;
  if (row >= B) return;
  const int64_t base = (int64_t)row * (int64_t)D;
  // Vectorized CUTE views over the row (float4 granularity).
  const int Dv = D >> 2;  // number of float4 elements in a row
  Tensor gA = make_tensor(
      make_gmem_ptr(reinterpret_cast<const float4*>(A + base)),
      make_shape(Dv));
  Tensor gP = make_tensor(
      make_gmem_ptr(reinterpret_cast<const float4*>(P + base)),
      make_shape(Dv));
  Tensor gN = make_tensor(
      make_gmem_ptr(reinterpret_cast<const float4*>(N + base)),
      make_shape(Dv));
  float dp0 = 0.0f;  // sum (a - p)^2 partial (chunk 0)
  float dp1 = 0.0f;  // sum (a - p)^2 partial (chunk 1)
  float dp2 = 0.0f;  // sum (a - p)^2 partial (chunk 2)
  float dp3 = 0.0f;  // sum (a - p)^2 partial (chunk 3)
  float dn0 = 0.0f;  // sum (a - n)^2 partial (chunk 0)
  float dn1 = 0.0f;  // sum (a - n)^2 partial (chunk 1)
  float dn2 = 0.0f;  // sum (a - n)^2 partial (chunk 2)
  float dn3 = 0.0f;  // sum (a - n)^2 partial (chunk 3)
  // Warp-stride partition of the row across the warp's lanes.
  // Unrolled by four: each iteration issues twelve independent 16-byte
  // vectorized loads (four float4 per operand) before dependent FMAs.
  // The deeper unroll increases memory-level parallelism (more
  // outstanding loads per warp), which better saturates DRAM bandwidth
  // for this bandwidth-bound streaming reduction.
  int i = lane;
  for (; i + 96 < Dv; i += 128) {
    const float4 a0 = __ldcs(&gA(i));
    const float4 a1 = __ldcs(&gA(i + 32));
    const float4 a2 = __ldcs(&gA(i + 64));
    const float4 a3 = __ldcs(&gA(i + 96));
    const float4 p0 = __ldcs(&gP(i));
    const float4 p1 = __ldcs(&gP(i + 32));
    const float4 p2 = __ldcs(&gP(i + 64));
    const float4 p3 = __ldcs(&gP(i + 96));
    const float4 n0 = __ldcs(&gN(i));
    const float4 n1 = __ldcs(&gN(i + 32));
    const float4 n2 = __ldcs(&gN(i + 64));
    const float4 n3 = __ldcs(&gN(i + 96));
    float d;
    d = a0.x - p0.x; dp0 += d * d;
    d = a0.y - p0.y; dp0 += d * d;
    d = a0.z - p0.z; dp0 += d * d;
    d = a0.w - p0.w; dp0 += d * d;
    d = a1.x - p1.x; dp1 += d * d;
    d = a1.y - p1.y; dp1 += d * d;
    d = a1.z - p1.z; dp1 += d * d;
    d = a1.w - p1.w; dp1 += d * d;
    d = a2.x - p2.x; dp2 += d * d;
    d = a2.y - p2.y; dp2 += d * d;
    d = a2.z - p2.z; dp2 += d * d;
    d = a2.w - p2.w; dp2 += d * d;
    d = a3.x - p3.x; dp3 += d * d;
    d = a3.y - p3.y; dp3 += d * d;
    d = a3.z - p3.z; dp3 += d * d;
    d = a3.w - p3.w; dp3 += d * d;
    d = a0.x - n0.x; dn0 += d * d;
    d = a0.y - n0.y; dn0 += d * d;
    d = a0.z - n0.z; dn0 += d * d;
    d = a0.w - n0.w; dn0 += d * d;
    d = a1.x - n1.x; dn1 += d * d;
    d = a1.y - n1.y; dn1 += d * d;
    d = a1.z - n1.z; dn1 += d * d;
    d = a1.w - n1.w; dn1 += d * d;
    d = a2.x - n2.x; dn2 += d * d;
    d = a2.y - n2.y; dn2 += d * d;
    d = a2.z - n2.z; dn2 += d * d;
    d = a2.w - n2.w; dn2 += d * d;
    d = a3.x - n3.x; dn3 += d * d;
    d = a3.y - n3.y; dn3 += d * d;
    d = a3.z - n3.z; dn3 += d * d;
    d = a3.w - n3.w; dn3 += d * d;
  }
  for (; i < Dv; i += 32) {
    const float4 av = __ldcs(&gA(i));
    const float4 pv = __ldcs(&gP(i));
    const float4 nv = __ldcs(&gN(i));
    float d;
    d = av.x - pv.x; dp0 += d * d;
    d = av.y - pv.y; dp0 += d * d;
    d = av.z - pv.z; dp0 += d * d;
    d = av.w - pv.w; dp0 += d * d;
    d = av.x - nv.x; dn0 += d * d;
    d = av.y - nv.y; dn0 += d * d;
    d = av.z - nv.z; dn0 += d * d;
    d = av.w - nv.w; dn0 += d * d;
  }
  float dp = (dp0 + dp1) + (dp2 + dp3);
  float dn = (dn0 + dn1) + (dn2 + dn3);
  // Scalar tail for rows whose length is not a multiple of 4.
  if ((D & 3) != 0) {
    Tensor tA = make_tensor(make_gmem_ptr(A + base), make_shape(D));
    Tensor tP = make_tensor(make_gmem_ptr(P + base), make_shape(D));
    Tensor tN = make_tensor(make_gmem_ptr(N + base), make_shape(D));
    for (int i = (Dv << 2) + lane; i < D; i += 32) {
      const float a = __ldcs(&tA(i));
      const float d1 = a - __ldcs(&tP(i));
      const float d2 = a - __ldcs(&tN(i));
      dp += d1 * d1;
      dn += d2 * d2;
    }
  }
  // Warp-local reduction of both partial sums using warp shuffles.
  // Since one warp owns one full row, no shared memory and no CTA-wide
  // synchronization are needed.
  #pragma unroll
  for (int off = 16; off > 0; off >>= 1) {
    dp += __shfl_down_sync(0xffffffffu, dp, off);
    dn += __shfl_down_sync(0xffffffffu, dn, off);
  }
  if (lane == 0) {
    const float dist_pos = sqrtf(dp);
    const float dist_neg = sqrtf(dn);
    const float loss = fmaxf(dist_pos - dist_neg + margin, 0.0f);
    if (loss > 0.0f) {
      atomicAdd(out, loss * inv_n);  // mean reduction fused here
    }
  }
}
torch::Tensor triplet_margin_loss(torch::Tensor anchor,
                                  torch::Tensor positive,
                                  torch::Tensor negative,
                                  double margin)
{
  TORCH_CHECK(anchor.is_cuda() && positive.is_cuda() && negative.is_cuda(),
              "anchor, positive and negative must be CUDA tensors");
  TORCH_CHECK(anchor.scalar_type() == at::kFloat &&
              positive.scalar_type() == at::kFloat &&
              negative.scalar_type() == at::kFloat,
              "Expect float32 tensors");
  TORCH_CHECK(anchor.sizes() == positive.sizes() &&
              anchor.sizes() == negative.sizes(),
              "anchor, positive and negative must have identical shapes");
  TORCH_CHECK(anchor.dim() >= 1, "inputs must have at least 1 dimension");
  auto a_c = anchor.contiguous();
  auto p_c = positive.contiguous();
  auto n_c = negative.contiguous();
  const int64_t D = a_c.size(-1);
  const int64_t B = a_c.numel() / D;
  TORCH_CHECK(B > 0 && D > 0, "inputs must be non-empty");
  auto out = torch::zeros({}, a_c.options());
  constexpr int Threads = 512;
  constexpr int Warps = Threads / 32;
  dim3 block(Threads);
  dim3 grid((unsigned)((B + Warps - 1) / Warps));
  const float inv_n = 1.0f / (float)B;

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  triplet_margin_loss_kernel<Threads><<<grid, block, 0, stream>>>(
      a_c.data_ptr<float>(),
      p_c.data_ptr<float>(),
      n_c.data_ptr<float>(),
      out.data_ptr<float>(),
      (int)B, (int)D,
      (float)margin, inv_n);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess,
              "triplet_margin_loss_kernel launch failed: ",
              cudaGetErrorString(err));

  return out;
}
"""

triplet_ext = load_inline(
    name="cute_triplet_margin_loss_ext",
    cpp_sources=triplet_cpp_decl,
    cuda_sources=triplet_cuda_src,
    functions=["triplet_margin_loss"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Triplet Margin Loss (p=2, mean reduction) computed entirely by a single
    fused custom CUDA kernel written with CuTe tensors:
        loss = mean_i max(||a_i - p_i||_2 - ||a_i - n_i||_2 + margin, 0)
    """
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = float(margin)
        self._ext = triplet_ext

    def forward(self, anchor, positive, negative):
        if not anchor.is_cuda:
            # CPU fallback preserving exact PyTorch semantics.
            return F.triplet_margin_loss(
                anchor, positive, negative, margin=self.margin)
        return self._ext.triplet_margin_loss(
            anchor, positive, negative, self.margin)

